#include "ff9.h"

void func_8002E718(RECT *r, s32 otz, MenuList *m) {
    s32 blink = ((u32)D_80077150 >> 4) & 1;
    u8 more = m->unk5 < m->unk2 - m->unk3;
    s32 x;
    s32 y;

    func_800275DC(r->x + r->w - 6, r->y + 5, otz, 0xB8, m->unk5 != 0 ? blink : 1);
    y = r->y + r->h - 14;
    x = r->x + r->w - 6;
    func_800275DC(x, y, otz, 0xB9, more ? blink : 1);
}
